import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"第四阶段 · 主动服务与手机入口","description":"在有限授权内主动工作，并把手机作为审批和接管入口。","frontmatter":{"title":"第四阶段 · 主动服务与手机入口","description":"在有限授权内主动工作，并把手机作为审批和接管入口。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4.md","filePath":"delivery/stage-4.md","lastUpdated":1794209603000}'),d={name:"delivery/stage-4.md"};function i(h,t,o,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="第四阶段-·-主动服务与手机入口" tabindex="-1">第四阶段 · 主动服务与手机入口 <a class="header-anchor" href="#第四阶段-·-主动服务与手机入口" aria-label="Permalink to &quot;第四阶段 · 主动服务与手机入口&quot;">​</a></h1><p>当前实现、已验证范围和明确留空项见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现代码闭环：</strong> 六类触发条件、带来源与风险说明的主动建议、主动收件箱（接受、忽略、稍后提醒、转任务）、注意力预算、安静时段和暂停入口；Web 端提供可安装 PWA 壳、离线应用壳和移动底部导航。</li><li><strong>仍未完成：</strong> iOS/Android 真机安装验收、手机配对、系统推送、远程审批与接管，以及 5–10 个真实主动任务的打扰验收。逐项证据见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第四阶段让 Hearth 在有限授权内主动工作，并把手机变成查看、审批和接管入口。重点不是“自动运行”，而是在正确的时间做正确的事，并且不制造打扰。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-4/4-1.html">4.1 设置触发条件与主动建议</a></td><td>发现值得处理的事，并解释为什么现在重要。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-2.html">4.2 建立主动收件箱</a></td><td>把建议集中到一个容易判断和处理的地方。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-3.html">4.3 手机查看、审批与接管</a></td><td>手机只保留关键动作和短期权限，丢失后可立即撤销。</td></tr><tr><td><a href="/hearth-os/delivery/stage-4/4-4.html">4.4 控制打扰与验收主动服务</a></td><td>主动模式要安静、有用、可控，并且可以随时关掉。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先建立触发条件和主动建议，不直接自动执行。</li><li>再把建议集中到主动收件箱，让用户决定接受、忽略或转成任务。</li><li>然后交付手机入口，支持查看、审批和接管。</li><li>最后用注意力预算和真实任务验收，确保主动模式安静、可控、可撤销。</li></ol>',10)])])}const p=e(d,[["render",i]]);export{m as __pageData,p as default};
